const item = $input.item;
const j = item.json || {};
const jobId = (j.jobId || "").trim();
const assetKey = (j.assetKey || "").trim();
const assetType = (j.assetType || "").trim();
const language = j.language || "ar";
const binaryObj = item.binary && item.binary.data ? item.binary.data : null;

if (!jobId) {
  return {
    json: {
      ok: false,
      jobId,
      assetKey,
      assetType,
      errorCode: "MISSING_JOB_ID",
      errorMessage: "jobId is required for image optimization."
    }
  };
}
if (!assetKey) {
  return {
    json: {
      ok: false,
      jobId,
      assetKey,
      assetType,
      errorCode: "MISSING_ASSET_KEY",
      errorMessage: "assetKey is required for image optimization."
    }
  };
}
if (!assetType) {
  return {
    json: {
      ok: false,
      jobId,
      assetKey,
      assetType,
      errorCode: "MISSING_ASSET_TYPE",
      errorMessage: "assetType is required for image optimization."
    }
  };
}
if (!binaryObj || !binaryObj.data) {
  return {
    json: {
      ok: false,
      jobId,
      assetKey,
      assetType,
      errorCode: "MISSING_BINARY_IMAGE",
      errorMessage: "No binary image data supplied for image optimization."
    }
  };
}

let sharp = null;
try {
  sharp = require("sharp");
} catch (e) {
  sharp = null;
}

if (!sharp) {
  return {
    json: {
      ok: false,
      jobId,
      assetKey,
      assetType,
      errorCode: "IMAGE_CONVERTER_NOT_CONFIGURED",
      errorMessage: "Image converter (Sharp module) is not configured in this n8n instance. Requires environment variable NODE_FUNCTION_ALLOW_EXTERNAL=sharp and npm install sharp."
    }
  };
}

const crypto = require("crypto");
const inputBuffer = Buffer.from(binaryObj.data, "base64");
const sharpInstance = sharp(inputBuffer);

return sharpInstance
  .metadata()
  .then(meta => {
    if (!meta || !meta.width || !meta.height) {
      throw new Error("Could not extract valid width/height metadata from image input.");
    }
    return sharpInstance
      .webp({ quality: 82 })
      .toBuffer()
      .then(webpBuffer => {
        const fileSizeBytes = webpBuffer.length;
        const checksum = crypto.createHash("sha256").update(webpBuffer).digest("hex");
        const base64WebP = webpBuffer.toString("base64");
        const width = meta.width;
        const height = meta.height;
        return {
          json: {
            ok: true,
            jobId,
            assetKey,
            assetType,
            language,
            width,
            height,
            fileSizeBytes,
            checksum,
            mimeType: "image/webp"
          },
          binary: {
            data: {
              data: base64WebP,
              mimeType: "image/webp",
              fileName: `${assetKey}.webp`,
              fileExtension: "webp",
              fileSize: `${fileSizeBytes} B`
            }
          }
        };
      });
  })
  .catch(err => {
    return {
      json: {
        ok: false,
        jobId,
        assetKey,
        assetType,
        errorCode: "WEBP_CONVERSION_FAILED",
        errorMessage: "Sharp WebP conversion failed: " + err.message
      }
    };
  });

const item = $input.item;
const opt = item.json || {};
const norm = {
  success: true,
  jobId: opt.jobId,
  status: "ASSET_OPTIMIZED",
  message: "Image converted to WebP and optimized successfully.",
  data: {
    assetKey: opt.assetKey,
    assetType: opt.assetType,
    width: opt.width,
    height: opt.height,
    fileSizeBytes: opt.fileSizeBytes,
    checksum: opt.checksum,
    mimeType: opt.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["upload_media"]
};
return {
  json: {
    jobId: opt.jobId,
    assetKey: opt.assetKey,
    assetType: opt.assetType,
    language: opt.language,
    width: opt.width,
    height: opt.height,
    fileSizeBytes: opt.fileSizeBytes,
    checksum: opt.checksum,
    mimeType: opt.mimeType,
    normalized: norm
  },
  binary: item.binary
};

const j = $json || {};
const code = j.errorCode || "IMAGE_CONVERTER_NOT_CONFIGURED";
const message = j.errorMessage || "Image converter is not configured in this n8n instance.";
const status = code === "IMAGE_CONVERTER_NOT_CONFIGURED" ? "NOT_CONFIGURED" : "FAILED";
return {
  json: {
    success: false,
    jobId: j.jobId || null,
    assetKey: j.assetKey || null,
    assetType: j.assetType || null,
    status,
    message,
    data: null,
    warnings: [],
    errors: [{ code, language: null, path: null, message }],
    nextAllowedActions: ["retry", "cancel"]
  },
  binary: $input.item ? $input.item.binary : undefined
};
